(357419, 28524, 7033, '<td valign="top">I''m jealous... this is a fantastic moon shot!  Perfectly crisp, with fantastic detail, especially at the limb.  Are you using a telescope, or just a REALLY long lens?  --10</td>', 'I''m jealous... this is a fantastic moon shot!  Perfectly crisp, with fantastic detail, especially at the limb.  Are you using a telescope, or just a REALLY long lens?  --10', '2003-07-16 01:08:32.000000', NULL, 1),
(357420, 28550, 92, '<td valign="top">Unique and well done ! The choice to use b/w really adds to the old feel of this. Nice angle and lighting. My only change would MAYBE be the DOF. Not sure if that would be better as the DOF used helps blue the area behind the keys. GREAT photo :)</td>', 'Unique and well done ! The choice to use b/w really adds to the old feel of this. Nice angle and lighting. My only change would MAYBE be the DOF. Not sure if that would be better as the DOF used helps blue the area behind the keys. GREAT photo :)', '2003-07-16 01:08:44.000000', NULL, 1),
(357422, 28453, 92, '<td valign="top">Beautiful colors and texture !</td>', 'Beautiful colors and texture !', '2003-07-16 01:09:18.000000', NULL, 1),
