(358034, 28888, 6938, '<td valign="top">Perhaps another angle or a closer crop would have drawn more attention to the subject rock.</td>', 'Perhaps another angle or a closer crop would have drawn more attention to the subject rock.', '2003-07-16 06:41:30.000000', NULL, 1),
