(358038, 28179, 6938, '<td valign="top">It is interesting the way the centre groove leads you into the scene.  Mabee a higher angle would have shown more of the grooves, and more charactor. I''m finding the blurred forground a bit distracting as well.  I like the concept.</td>', 'It is interesting the way the centre groove leads you into the scene.  Mabee a higher angle would have shown more of the grooves, and more charactor. I''m finding the blurred forground a bit distracting as well.  I like the concept.', '2003-07-16 06:45:02.000000', NULL, 1),
(358039, 28954, 7570, '<td valign="top">too bright, and i dislike the colours. too striking? not very interesting subject either that doesn''t give me a good sense of "round". hope you are not discouraged. try again.</td>', 'too bright, and i dislike the colours. too striking? not very interesting subject either that doesn''t give me a good sense of "round". hope you are not discouraged. try again.', '2003-07-16 06:50:01.000000', NULL, 1),
