(363014, 28304, 6325, '<td valign="top">Stunning.</td>', 'Stunning.', '2003-07-21 23:37:04.000000', NULL, 1),
(363015, 28770, 9644, '<td valign="top">Very cool Idea!</td>', 'Very cool Idea!', '2003-07-21 23:37:13.000000', NULL, 1),
(363016, 28611, 9644, '<td valign="top">I really like the interpetation of this</td>', 'I really like the interpetation of this', '2003-07-21 23:39:04.000000', NULL, 1),
(363017, 29179, 6325, '<td valign="top">Dramatic scene. Well lighted. The counter point of the two groupings of hay bales really sets it off.</td>', 'Dramatic scene. Well lighted. The counter point of the two groupings of hay bales really sets it off.', '2003-07-21 23:40:30.000000', NULL, 1),
(363018, 28407, 9644, '<td valign="top">I can see the idea but for some reason I just don''t like the cropping in this photo.</td>', 'I can see the idea but for some reason I just don''t like the cropping in this photo.', '2003-07-21 23:41:23.000000', NULL, 1),
(363035, 29196, 6938, '<td valign="top">Could the edge of the floor or table or base have been removed by moving the umbrellas back a bit so that you could crop it out?  The only polish needed on a interesting and well executed shot.</td>', 'Could the edge of the floor or table or base have been removed by moving the umbrellas back a bit so that you could crop it out?  The only polish needed on a interesting and well executed shot.', '2003-07-22 00:05:10.000000', NULL, 1),
(363072, 28249, 10260, '<td valign="top">very creative.  I like this.</td>', 'very creative.  I like this.', '2003-07-22 00:28:01.000000', NULL, 1),
(363102, 28931, 8981, '<td valign="top">I really like this shot.  Unfortunatly I get more of a linear line feeling than a round one.  This shot probably would have done better in a different challenge.  I do think it''s very interesting though.  Good job.</td>', 'I really like this shot.  Unfortunatly I get more of a linear line feeling than a round one.  This shot probably would have done better in a different challenge.  I do think it''s very interesting though.  Good job.', '2003-07-22 01:02:15.000000', NULL, 1),
(363104, 29181, 8981, '<td valign="top">Wow, very interesting.  This shot could have been just as good for the contrast challenge.  I like this, it shows depth and has a great feel about it!</td>', 'Wow, very interesting.  This shot could have been just as good for the contrast challenge.  I like this, it shows depth and has a great feel about it!', '2003-07-22 01:04:22.000000', NULL, 1),
(363107, 29089, 8981, '<td valign="top">I can barely see the round here.  I think you had a good idea, but the exposure/contrast is way to high here.  Looks kind of cool, but it definatly takes away from the point of the challenge.</td>', 'I can barely see the round here.  I think you had a good idea, but the exposure/contrast is way to high here.  Looks kind of cool, but it definatly takes away from the point of the challenge.', '2003-07-22 01:06:18.000000', NULL, 1),
(363112, 29155, 8981, '<td valign="top">You''re right, this is kind of dizzying.  I think that there is too much light reflecting around in this picture.  There looks like there are little specs of white around some of the marbles.  Using Neat Image could help this.  I don''t know, experiment a little :)</td>', 'You''re right, this is kind of dizzying.  I think that there is too much light reflecting around in this picture.  There looks like there are little specs of white around some of the marbles.  Using Neat Image could help this.  I don''t know, experiment a little :)', '2003-07-22 01:09:00.000000', NULL, 1),
(363116, 28672, 8981, '<td valign="top">Oooh, I really like this one.  This is a good, creative take on the eye theme that has been going on in this challenge.  Plus the picture is so detailed and sharp in all the right places.  GREAT JOB!</td>', 'Oooh, I really like this one.  This is a good, creative take on the eye theme that has been going on in this challenge.  Plus the picture is so detailed and sharp in all the right places.  GREAT JOB!', '2003-07-22 01:11:49.000000', NULL, 1),
(363119, 28301, 8981, '<td valign="top">Wow, that is pretty cool.  I would actually like to know how you did this.  Nice shot!</td>', 'Wow, that is pretty cool.  I would actually like to know how you did this.  Nice shot!', '2003-07-22 01:12:34.000000', NULL, 1),
(363124, 28865, 6938, '<td valign="top">Very interesting.  It seems a bit dull in general.......   Mabe a time closer to midday would have povided a better light?</td>', 'Very interesting.  It seems a bit dull in general.......   Mabe a time closer to midday would have povided a better light?', '2003-07-22 01:19:02.000000', NULL, 1),
(363126, 29142, 6938, '<td valign="top">Very clever!</td>', 'Very clever!', '2003-07-22 01:20:05.000000', NULL, 1),
(363127, 28822, 6938, '<td valign="top">I think the white background is a bit to contrasting.....  The general lighting is very good.<br/></td>', 'I think the white background is a bit to contrasting.....  The general lighting is very good.', '2003-07-22 01:21:13.000000', NULL, 1),
(363144, 28110, 6938, '<td valign="top">Perhaps a faster shutter would have solidified the dog and made it more a part of the scene rather than a distraction.   I like the idea.</td>', 'Perhaps a faster shutter would have solidified the dog and made it more a part of the scene rather than a distraction.   I like the idea.', '2003-07-22 01:38:43.000000', NULL, 1),
(363157, 28410, 9115, '<td valign="top">Good photo!  I think it could have been improved slightly, however, by cropping it slightly at the top to cut out the grass and the red object.</td>', 'Good photo!  I think it could have been improved slightly, however, by cropping it slightly at the top to cut out the grass and the red object.', '2003-07-22 02:06:48.000000', NULL, 1),
(363170, 28483, 6938, '<td valign="top">Perhaps less milk or more Cheerios would have looked a bit better.  More circles to look at with a bit more character.  (hypethetically of course ;o)  )</td>', 'Perhaps less milk or more Cheerios would have looked a bit better.  More circles to look at with a bit more character.  (hypethetically of course ;o)  )', '2003-07-22 02:47:59.000000', NULL, 1),
(363180, 28464, 6938, '<td valign="top">Too much manipulation for the effect. ( a slight clockwise rotation may have helped as well).   An interesting Idea, but the details have been lost.</td>', 'Too much manipulation for the effect. ( a slight clockwise rotation may have helped as well).   An interesting Idea, but the details have been lost.', '2003-07-22 03:41:18.000000', NULL, 1),
(363191, 28082, 8298, '<td valign="top">nice</td>', 'nice', '2003-07-22 04:10:43.000000', NULL, 1);
