(363277, 28559, 8298, '<td valign="top">original. great hue, awesome crop. nice reflections. good focus. lost marks for that distracting element (that i''m sure many have commented on). overall, very solid submission. 7</td>', 'original. great hue, awesome crop. nice reflections. good focus. lost marks for that distracting element (that i''m sure many have commented on). overall, very solid submission. 7', '2003-07-22 08:09:40.000000', NULL, 1),
