(363311, 28954, 8891, '<td valign="top">yes....it is</td>', 'yes....it is', '2003-07-22 09:39:02.000000', NULL, 1),
(363316, 28913, 8891, '<td valign="top">spectacularrrrrrrrrrr pattern shot...like all the rounds in rounds and rounds by rounds very cool.....but did you have to not abide by the rule of thirds? hmmmm let''s see.....yep you did...I think...maybe losing the left side but to the first set of pillars? Maybe...like it anyway!</td>', 'spectacularrrrrrrrrrr pattern shot...like all the rounds in rounds and rounds by rounds very cool.....but did you have to not abide by the rule of thirds? hmmmm let''s see.....yep you did...I think...maybe losing the left side but to the first set of pillars? Maybe...like it anyway!', '2003-07-22 09:44:41.000000', NULL, 1),
(363321, 28602, 8891, '<td valign="top">Like the round against the rectangle....I would have emphasized, perhaps, the round reflections of the box on the balls and lost the lid all together. The lid, even a hint of it distracts me. Do not like the hot spots on the balls.</td>', 'Like the round against the rectangle....I would have emphasized, perhaps, the round reflections of the box on the balls and lost the lid all together. The lid, even a hint of it distracts me. Do not like the hot spots on the balls.', '2003-07-22 09:51:03.000000', NULL, 1),
