(363333, 28410, 8891, '<td valign="top">I definitely like this....just needs to have the bit of horizon cropped....love the would richness of the green on the let that leads to great muted tones throught to the right and the wonderful texture contrasts.  NICE!</td>', 'I definitely like this....just needs to have the bit of horizon cropped....love the would richness of the green on the let that leads to great muted tones throught to the right and the wonderful texture contrasts.  NICE!', '2003-07-22 10:05:42.000000', NULL, 1),
