(366254, 29126, 472, '<td valign="top">i was very lucky this day - the skies were insane.  actually it was terry (clubjuggle) who first noticed this particular vista - the way the skies looked behind the capitol.  funny, i still haven''t seen his shots from that day (but one, his entry for this challenge).</td>', 'i was very lucky this day - the skies were insane.  actually it was terry (clubjuggle) who first noticed this particular vista - the way the skies looked behind the capitol.  funny, i still haven''t seen his shots from that day (but one, his entry for this challenge).', '2003-07-24 20:00:19.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
